#[inline(never)]
fn tree6(a: u32, b: u32) -> u32 {
    let x = b;
    if (a >> 1) & 1 == 0 {
        if (a >> 6) & 1 == 0 {
            x | 0x8008
        } else {
            x.wrapping_add(0x9009)
        }
    } else {
        if (a >> 6) & 1 == 0 {
            x ^ 0xa00a
        } else {
            x.rotate_left(11)
        }
    }
}

#[inline(never)]
fn chain48(a: u32, b: u32) -> u32 {
    let mut x = b;
    if (a >> 0) & 1 == 1 {
        x = x.wrapping_mul(9);
    }
    if (a >> 7) & 1 == 1 {
        x = x.wrapping_sub(0x5005);
    }
    x
}

#[unsafe(no_mangle)]
pub extern "C" fn entrypoint(input1: u32, input2: u32) -> u32 {
    match64(input1, input2)
        ^ tree6(input2, input1).rotate_left(9)
        ^ chain48(input1 ^ input2, input2).rotate_left(18)
}
